function handleDowngrade(sub: Subscription, newPlan: Plan, now: Date) {
  const cycleDays = 30;
  const currentDay = getDayIndex(sub.cycleStart, now);

  // Req 1: Exclude downgrade date.
  // If currentDay is 0, remaining is 29 days (days 1..29).
  const remainingDays = cycleDays - 1 - currentDay;

  const dailyRate = sub.currentPlan.grossPrice / cycleDays;
