CODE:
def validate_payment(pay: dict) -> dict:
    if pay["amount"] >= 50000 and pay["approval_count"] < 2:
        return {"status": "REJECT", "reason": "DUAL_APPROVAL_MISSING"}
    if pay["currency"] not in ["USD", "EUR"]:
        return {"status": "REJECT", "reason": "INVALID_CURRENCY"}
    diff_mins = (pay["batch_cutoff_ts"] - pay["submitted_ts"]).total_seconds() / 60
    pay["is_urgent"] = diff_mins < 120
    if is_weekend(pay["date"]) and not (pay["is_urgent"] and pay["amount"] < 5000):
        return {"status": "REJECT", "reason": "WEEKEND_BLOCK"}
    if pay["region"] == "EU" and abs(pay["vat_amount"] - pay["net"] * pay["rate"]) > 0.01:
        return {"status": "REJECT", "reason": "VAT_MISMATCH"}
    return {"status": "ACCEPT"}

