package middleware

import (
    "fmt"
    "net/http"
    "sync"
    "time"
)

type RateLimiter struct {
    mu      sync.Mutex
    tenants map[string]*window
    def     *window
}

type window struct {
    timestamps []time.Time
}

func NewRateLimiter() *RateLimiter {
    return &RateLimiter{
        tenants: make(map[string]*window),
        def:     &window{},
    }
}

func (rl *RateLimiter) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    rl.mu.Lock()
    defer rl.mu.Unlock()

    tenantID := r.Header.Get("X-Tenant-Context")
    limit := 100
    win := rl.def
    if tenantID != "" {
        if _, exists := rl.tenants[tenantID]; !exists {
            rl.tenants[tenantID] = &window{}
        }
        win = rl.tenants[tenantID]
    } else {
        limit = 50
    }

    now := time.Now()
    cutoff := now.Add(-60 * time.Second)
    win.timestamps = filterRecent(win.timestamps, cutoff)

    if len(win.timestamps) >= limit {
        oldest := win.timestamps[0]
        retryAfter := int(oldest.Add(60 * time.Second).Sub(now).Seconds()) + 1
        if retryAfter < 1 {
            retryAfter = 1
        }
        w.Header().Set("Retry-After", fmt.Sprintf("%d", retryAfter))
        log.Warn().Str("tenant_id", tenantID).Int("req_count", len(win.timestamps)).Int("limit", limit).Time("timestamp", now).Msg("rate limit exceeded")
        w.WriteHeader(http.StatusTooManyRequests)
        return
    }

    win.timestamps = append(win.timestamps, now)
    next(r)
}

func filterRecent(ts []time.Time, cutoff time.Time) []time.Time {
    var valid []time.Time
    for _, t := range ts {
        if !t.Before(cutoff) {
            valid = append(valid, t)
        }
    }
    return valid
}

