During routine dependency auditing and pipeline execution, the SAST pipeline flagged a logic flaw in the JWT validation middleware introduced in PR #4491. The flaw allows expired tokens to be silently re-validated if a specific legacy header flag is present. This bypasses the session expiration controls mandated by PCI-DSS requirement 8.3.6 and internal policy SEC-AUTH-11. The vulnerability affects the production auth-gateway service (v3.4.0-rc1) and the staging environment. Immediate containment is required before the scheduled Friday release train. The affected endpoints include /api/v2/payments/init and /api/v2/user/profile. Customer-facing impact is limited to potential session hijacking if an attacker controls the legacy header.

CODE DIFF (PR #4491 excerpt)
--- a/src/middleware/validate_token.js
+++ b/src/middleware/validate_token.js
@@ -14,12 +14,14 @@
const crypto = require('crypto-utils@2.1.0');
const { verify } = require('jsonwebtoken');

function validateToken(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];
  const bypassFlag = req.headers['x-legacy-bypass'] === 'true';

  try {
-    const payload = verify(token, process.env.JWT_SECRET);
-    req.user = payload;
-    return next();
+    if (bypassFlag && crypto.isLegacyFormat(token)) {
+      req.user = { sub: 'legacy', scope: 'read' };
+      return next();
+    }
+    const payload = verify(token, process.env.JWT_SECRET);
+    req.user = payload;
+    return next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

