Ticket: JIRA-4491 | Priority: High | Sprint: 24-19
Objective: Implement idempotent retry logic for third-party carrier API calls to prevent duplicate shipment bookings during transient network failures. Historical data indicates a 4.2% duplication rate during peak logistics hours, directly impacting carrier reconciliation and customer billing accuracy.
Explicit Requirements:
1. Retry mechanism must be strictly idempotent, utilizing a request fingerprint hash stored in Redis to prevent duplicate processing.
2. Maximum timeout per individual request attempt must not exceed 5000ms to prevent thread pool exhaustion.
3. All retry events and final outcomes must be emitted as structured JSON logs to the dedicated audit path: /var/log/omni/shipment_audit.
4. HTTP response must return status 202 Accepted upon successful queue ingestion, regardless of background processing state.
5. Code must pass linting, unit tests, and integration smoke tests with zero critical warnings.

SECTION 2: CODE IMPLEMENTATION (DIFF/EXCERPT)
// File: src/services/carrierGateway.ts
// Lines: 42-91 (50 lines total)
import { createHash } from 'crypto';
import { redisClient } from '../config/cache';
import { logger } from '../utils/logging';
import axios, { AxiosError } from 'axios';

export async function submitShipment(payload: ShipmentPayload, carrierId: string): Promise<number> {
  const fingerprint = createHash('sha256').update(JSON.stringify(payload)).digest('hex');
  const retryKey = `retry:${carrierId}:${fingerprint}`;

  // Check idempotency
  const existing = await redisClient.get(retryKey);
  if (existing) {
    logger.info(`Idempotent match found for ${fingerprint}`);
    return 202;
  }

  const maxAttempts = 3;
  let lastError: AxiosError | null = null;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      const response = await axios.post(`https://api.carrier-v2.com/v1/book`, payload, {
        timeout: 5000,
        headers: { 'X-Request-Id': fingerprint }
      });

      await redisClient.setEx(retryKey, 3600, 'processed');
      logger.info('Shipment queued successfully', { carrierId, fingerprint, attempt });
      return 202;
    } catch (err) {
      lastError = err as AxiosError;
      logger.warn(`Attempt ${attempt} failed: ${lastError.message}`);
      if (attempt < maxAttempts) {
        await new Promise(r => setTimeout(r, 200 * attempt));
      }
    }
  }

  logger.error('All retry attempts exhausted', { carrierId, fingerprint, error: lastError?.message });
  return 500;
}

